import re

MARK = re.compile(r'^(\s*)\d+\)\s?(.*)$')

def val(s):
    s = s.strip()
    m = re.match(r'^\(integer\)\s+(-?\d+)$', s)
    if m:
        return int(m.group(1))
    if len(s) >= 2 and s[0] == '"' and s[-1] == '"':
        return s[1:-1]
    return s

def parse(lines):
    items = []
    nested_col = None
    for i, l in enumerate(lines):
        m = MARK.match(l)
        if not m:
            continue
        col = len(m.group(1))
        rest = m.group(2)
        m2 = MARK.match(rest)
        if m2:
            nested_col = len(l) - len(rest) + len(m2.group(1))
            items.append((0, i, None))
            items.append((1, i, m2.group(2)))
        elif nested_col is not None and col >= nested_col:
            items.append((1, i, rest))
        else:
            nested_col = None
            items.append((0, i, rest))
    kv = {}
    kvlines = []
    rows = []
    rowlines = []
    j = 0
    while j < len(items):
        lv, i, t = items[j]
        if lv != 0 or t is None:
            j += 1
            continue
        if j + 1 >= len(items):
            kv[str(val(t))] = ''
            kvlines.append(i)
            break
        lv2, i2, t2 = items[j + 1]
        if t2 is None:
            row = {'db': val(t)}
            ls = [i, i2]
            k = j + 2
            sub = []
            while k < len(items) and items[k][0] == 1:
                sub.append(items[k])
                k += 1
            for a in range(0, len(sub) - 1, 2):
                row[str(val(sub[a][2]))] = val(sub[a + 1][2])
            ls += [x[1] for x in sub]
            rows.append(row)
            rowlines += ls
            j = k
        elif lv2 == 0:
            kv[str(val(t))] = val(t2)
            kvlines += [i, i2]
            j += 2
        else:
            j += 1
    blocks = []
    if kv:
        blocks.append({'name': 'memory_stats', 'kind': 'kv', 'lines': sorted(set(kvlines)), 'records': [kv]})
    if rows:
        blocks.append({'name': 'databases', 'kind': 'table', 'lines': sorted(set(rowlines)), 'records': rows})
    return {'blocks': blocks, 'skip': []}
